/// <summary>
/// Constructs the reference identities used to populate the <c>METTransferOrderExtractScreen</c> form.
/// </summary>
public  class METTransferOrderExtractScreenProcessor
{
    METTransferOrderExtractScreenTmp metTransferOrderExtractScreenTmp;
    METTransferOrderExtractScreenParameters filterParms;
    METTotalPallets totalPallets;
    METTotalPallets totalActualPallets;

	//Bug 229712 CB628 - Update status in extraction screen got refresh issue -start
    boolean recordsFound;
}

Method.Source:
	//Bug 229712 CB628 - Update status in extraction screen got refresh issue -end

    /// <summary>
    /// Sets total pallets
    /// </summary>
    /// <param name = "_pallets">
    /// Total pallets
    /// </param>
    /// <returns>
    /// Pallets
    /// </returns>
    public METTotalPallets parmTotalpallets(METTotalPallets _pallets = totalPallets)
    {
        totalPallets = _pallets;
        return totalPallets;
    }

/// <summary>
/// Sets total actual pallets
/// </summary>
/// <param name = "_actualPallets">
/// Total actual pallets
/// </param>
/// <returns>
/// Actual Pallets
/// </returns>
public METTotalPallets parmTotalActualpallets(METTotalPallets _actualPallets = totalActualPallets)
{
    totalActualPallets = _actualPallets;
    return totalActualPallets;
}

/// <summary>
/// set or get <c>METTransferOrderExtractScreenParameters</c> class instance.
/// </summary>
/// <param name = "_metTransferOrderExtractScreenParameters"><c>METTransferOrderExtractScreenParameters</c> class instance.</param>
/// <returns><c>METTransferOrderExtractScreenParameters</c> class instance</returns>
public METTransferOrderExtractScreenParameters parmMETTransferOrderExtractScreenParams(METTransferOrderExtractScreenParameters _filterParms = filterParms)
{
    filterParms = _filterParms;
    return filterParms;
}

    /// <summary>
    /// set or get <c>METTransferOrderExtractScreenTmp</c> table instance.
    /// </summary>
    /// <param name = "_metTransferOrderExtractScreenTmp"><c>METTransferOrderExtractScreenTmp</c> table instance</param>
    /// <returns><c>METTransferOrderExtractScreenTmp</c> table instance</returns>
    public METTransferOrderExtractScreenTmp parmMETTransferOrderExtractScreenTmp(
        METTransferOrderExtractScreenTmp _metTransferOrderExtractScreenTmp = metTransferOrderExtractScreenTmp)
    {
        metTransferOrderExtractScreenTmp.linkPhysicalTableInstance(_metTransferOrderExtractScreenTmp);

        return metTransferOrderExtractScreenTmp;
    }

    private METItemTypes getItemTypeCode(InventTransId _transferId, METFilterCodeone _filterCode)
    {
        METItemTypes itemType = '';
        InventTransferLine transLine;
        METInventItemOrderSetup metInventItemOrderSetupLoc;
        InventDim inventDimLoc;

        select count(RecId), ItemType from metInventItemOrderSetupLoc
            group by ItemType
            where metInventItemOrderSetupLoc.FilterCode == _filterCode
                exists join transLine
                    where transLine.ItemId == metInventItemOrderSetupLoc.ItemId
                        && transLine.TransferId == _transferId
                exists join inventDimLoc
                    where inventDimLoc.inventDimId == transLine.InventDimId
                        && inventDimLoc.InventSiteId == metInventItemOrderSetupLoc.SiteId;

        if (metInventItemOrderSetupLoc.RecId > 1)
        {
            itemType = METConstants::ItemTypeMultiple;
        }
        else
        {
            itemType = metInventItemOrderSetupLoc.ItemType;
        }

        return itemType;
    }

    /// <summary>
    /// Calculates the data for temporary table records
    /// </summary>
    /// <param name = "_metTransferOrderExtractScreenTmp">
    /// The temporary table buffer
    /// </param>
    /// <param name = "_fds">
    /// Form data source
    /// </param>
    /// <param name = "_selectedTransferIdMap">
    /// Tranfer Id map.
    /// </param>
    public container calculate(METTransferOrderExtractScreenTmp  _metTransferOrderExtractScreenTmp, Map _selectedTransferIdMap = null)    
    {
        Factor conversionFactor;

        METUOMVolume totalvolume;
        METUOMVolume totalactualVolume;
        METCase totalCases;
        METCase totalActualCases;
        METCase totalBrokenCases;
        METCase totalActualBrokenCases;
        Weight totalWeight;
        Weight totalActualWeight;
        

        #OCCRetryCount

        void setUnitFactors()
        {
            InventTransferLine transLineLoc;
            METInventTransferLine metTransLineLoc;
            
            while select forupdate metTransLineLoc
                where metTransLineLoc.TOUnitVolume == 0
                || metTransLineLoc.TOUnitVolumeEA == 0
                exists join transLineLoc
                where transLineLoc.RecId == metTransLineLoc.InventTransferLine
                && transLineLoc.TransferId == metTransferOrderExtractScreenTmp.TransferId
            {
                ttsbegin;
                metTransLineLoc.setUnitFields();
                metTransLineLoc.doUpdate();
                ttscommit;
            }
        }

        void setValues()
        {
            METInventTransferLineActuals transActualsReserve, transActualsOnOrder;
            InventTransferLine transLineActual;

            select sum(Cases), sum(BrokenCase), sum(TotalVolume), sum(TotalWeight), sum(ActualBrokenCases), 
                sum(ActualCases), sum(ActualVolume), sum(ActualWeight), sum(ActualWeightEA), sum(ActualVolumeEA)
                from transActualsReserve
                where transActualsReserve.StatusIssue == StatusIssue::ReservPhysical
                    exists join transLineActual
                        where transLineActual.RecId == transActualsReserve.RecId
                        && transLineActual.TransferId == metTransferOrderExtractScreenTmp.TransferId;

            if (transActualsReserve.ActualCases == 0)
            {
                select sum(Cases), sum(BrokenCase), sum(TotalVolume), sum(TotalWeight), sum(ActualBrokenCases), 
                    sum(ActualCases), sum(ActualVolume), sum(ActualWeight), sum(ActualWeightEA), sum(ActualVolumeEA)
                    from transActualsOnOrder
                    where transActualsOnOrder.StatusIssue == StatusIssue::OnOrder
                        exists join transLineActual
                        where transLineActual.RecId == transActualsOnOrder.RecId
                            && transLineActual.TransferId == metTransferOrderExtractScreenTmp.TransferId;
            }

            //Set values for form level summary
            totalPallets += real2int(transActualsReserve.PalletVolume ? transActualsReserve.PalletVolume : transActualsOnOrder.PalletVolume);
            totalActualPallets += real2int(transActualsReserve.ActualPalletVolume ? transActualsReserve.ActualPalletVolume : transActualsOnOrder.ActualPalletVolume);

            totalCases += real2int(transActualsReserve.Cases ? transActualsReserve.Cases : transActualsOnOrder.Cases);
            totalActualCases += real2int(transActualsReserve.ActualCases ? transActualsReserve.ActualCases : transActualsOnOrder.ActualCases);

            totalvolume += transActualsReserve.TotalVolume ? transActualsReserve.TotalVolume : transActualsOnOrder.TotalVolume;
            totalactualVolume += (transActualsReserve.ActualVolume ? transActualsReserve.ActualVolume : transActualsOnOrder.ActualVolume) + (transActualsReserve.ActualVolumeEA ? transActualsReserve.ActualVolumeEA : transActualsOnOrder.ActualVolumeEA);

            totalWeight += transActualsReserve.TotalWeight ? transActualsReserve.TotalWeight : transActualsOnOrder.TotalWeight;
            totalActualWeight += (transActualsReserve.ActualWeight ?  transActualsReserve.ActualWeight : transActualsOnOrder.ActualWeight) + (transActualsReserve.ActualWeightEA ? transActualsReserve.ActualWeightEA : transActualsOnOrder.ActualWeightEA);

            totalBrokenCases += real2int(transActualsReserve.BrokenCase ? transActualsReserve.BrokenCase : transActualsOnOrder.BrokenCase);
            totalActualBrokenCases += real2int(transActualsReserve.ActualBrokenCases ? transActualsReserve.ActualBrokenCases : transActualsOnOrder.ActualBrokenCases);
            
            
            metTransferOrderExtractScreenTmp.Cases = transActualsReserve.Cases ? transActualsReserve.Cases : transActualsOnOrder.Cases;
            metTransferOrderExtractScreenTmp.BrokenCase = transActualsReserve.BrokenCase ? transActualsReserve.BrokenCase : transActualsOnOrder.BrokenCase;
            metTransferOrderExtractScreenTmp.Volume = transActualsReserve.TotalVolume ? transActualsReserve.TotalVolume : transActualsOnOrder.TotalVolume;
            metTransferOrderExtractScreenTmp.Weight = transActualsReserve.TotalWeight ? transActualsReserve.TotalWeight : transActualsOnOrder.TotalWeight;
            metTransferOrderExtractScreenTmp.ItemType = this.getItemTypeCode(metTransferOrderExtractScreenTmp.TransferId, metTransferOrderExtractScreenTmp.FilterCodeOne);
            metTransferOrderExtractScreenTmp.ActualCases = real2int(transActualsReserve.ActualCases ? transActualsReserve.ActualCases : transActualsOnOrder.ActualCases);
            metTransferOrderExtractScreenTmp.ActualBrokenCase = real2int(transActualsReserve.ActualBrokenCases ? transActualsReserve.ActualBrokenCases : transActualsOnOrder.ActualBrokenCases);
            metTransferOrderExtractScreenTmp.ActualVolume = (transActualsReserve.ActualVolume ? transActualsReserve.ActualVolume : transActualsOnOrder.ActualVolume) + (transActualsReserve.ActualVolumeEA ? transActualsReserve.ActualVolumeEA : transActualsReserve.ActualVolumeEA);
            metTransferOrderExtractScreenTmp.ActualWeight = (transActualsReserve.ActualWeight ?  transActualsReserve.ActualWeight : transActualsOnOrder.ActualWeight) + (transActualsReserve.ActualWeightEA ? transActualsReserve.ActualWeightEA : transActualsOnOrder.ActualWeightEA);

            ttsbegin;
            metTransferOrderExtractScreenTmp.update();
            ttscommit;
        }

        try
        {
            totalPallets = this.parmTotalpallets();
            totalActualPallets = this.parmTotalActualpallets();

            metTransferOrderExtractScreenTmp.linkPhysicalTableInstance(_metTransferOrderExtractScreenTmp);

            //Reset previously calculated values to zero.
            update_recordset metTransferOrderExtractScreenTmp
                setting weight = 0, Volume = 0, Cases = 0, BrokenCase = 0, 
                    ActualBrokenCase = 0, ActualCases = 0, ActualVolume = 0, ActualWeight = 0;

            if(!_selectedTransferIdMap)
            {
                while select forupdate metTransferOrderExtractScreenTmp
                {
                    setUnitFactors();
                    setValues();
                }
            }
            else
            {
                MapEnumerator transEnum = _selectedTransferIdMap.getEnumerator();

                while (transEnum.moveNext())
                {
                    select forupdate firstonly metTransferOrderExtractScreenTmp 
                        where metTransferOrderExtractScreenTmp.TransferId == transEnum.currentValue();

                    setUnitFactors();
                    setValues();
                }
            }

            this.parmTotalpallets(totalPallets);
            this.parmTotalActualpallets(totalActualPallets);
        }
        catch (Exception::Error)
        {
            error("@MET:METBulkUpdateError");
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }

        return [totalCases, totalActualCases, totalvolume, totalactualVolume, totalWeight, totalActualWeight, totalBrokenCases, totalActualBrokenCases];
    }

    /// <summary>
    /// Constructs the transfer order extract screen.
    /// </summary>    
    /// <param name="_metTransferOrderExtractScreenParameters">
    /// An instance of <c>METTransferOrderExtractScreenParameters</c> to filter the order extract screen form.
    /// </param>
    /// <returns>
    /// METTransferOrderExtractScreenProcessor class instance.
    /// </returns>
    public static METTransferOrderExtractScreenProcessor construct(METTransferOrderExtractScreenParameters         _metTransferOrderExtractScreenParameters)
    {
        METTransferOrderExtractScreenProcessor   metTransferOrderExtractScreenProcessor;

        metTransferOrderExtractScreenProcessor = new METTransferOrderExtractScreenProcessor();

        metTransferOrderExtractScreenProcessor.parmMETTransferOrderExtractScreenParams(_metTransferOrderExtractScreenParameters);
   
        return metTransferOrderExtractScreenProcessor;
    }

    /// <summary>
    /// Populates the extract screen form by inserting records based on filters
    /// </summary>
    /// <returns>
    /// METTransferOrderExtractScreenTmp table buffer
    /// </returns>    
    public METTransferOrderExtractScreenTmp populateOrderExtractScreen()
    {
        METTransferOrderExtractScreenTmp metExtractScreenTmp;
        InventTransferTable inventTransferTable;
        METInventTransferTableExt metInventTransferTableExt;

        ReqItemTable reqItemTable;
        METReqItemTable metReqItemTable;
        InventDim inventDimReq;
        InventDim inventDim;
        METInventItemOrderSetup metInventItemOrderSetup;
        InventTransferLine inventTransferLine;

        //Step 1: Insert records that match the filter criteria choosen by customer
        insert_recordset metExtractScreenTmp(TransferId, OrderSplitGroup, Door, StagingLane)
            select TransferId from inventTransferTable
                where inventTransferTable.TransferStatus == InventTransferStatus::Created
                    && (!filterParms.parmFromWarehouse() 
                        || inventTransferTable.InventLocationIdFrom == filterParms.parmFromWarehouse())
                    && (!filterParms.parmToWarehouse()
                        || inventTransferTable.InventLocationIdTo == filterParms.parmToWarehouse())
                    && (inventTransferTable.ShipDate >=  filterParms.parmShippingDateConfirmFrom()
                        && inventTransferTable.ShipDate <=  filterParms.parmShippingDateConfirmTo())
            join OrderSplitGroup, Door, StagingLane from metInventTransferTableExt
                where metInventTransferTableExt.InventTransferTable == inventTransferTable.RecId
                    && metInventTransferTableExt.OrderExtractStatus == filterParms.parmExtracted()
                    && (!filterParms.parmRoute()  
                        || metInventTransferTableExt.Route == filterParms.parmRoute())
                    && (!filterParms.parmOrderSplitGroup() 
                        || metInventTransferTableExt.OrderSplitGroup == filterParms.parmOrderSplitGroup());

        //Update order split category code
        update_recordset metExtractScreenTmp
            setting OSCCode = metReqItemTable.OSCCode
        join RecId from inventTransferLine
            where inventTransferLine.TransferId == metExtractScreenTmp.TransferId
            && inventTransferLine.LineNum == metExtractScreenTmp.LineNum
        join RecId from inventDim
            where inventDim.inventDimId == inventTransferLine.InventDimId
        join Recid from reqItemTable
            where reqItemTable.ItemId == inventTransferLine.ItemId
        join OSCCode from metReqItemTable
            where metReqItemTable.RefRecId == reqItemTable.RecId
        exists join inventDimReq
            where inventDimReq.InventSiteId == inventDim.InventSiteId
            && InventDimReq.InventLocationId == inventDim.InventLocationId
            && inventDimReq.inventDimId == reqItemTable.CovInventDimId;

        select firstonly metExtractScreenTmp;
        if (metExtractScreenTmp.RecId)
        {
            this.parmTransferOrderRecordsFound(true);
        }
        return metExtractScreenTmp;
    }

/// <summary>
/// Bug 229712 CB628 - Update status in extraction screen got refresh issue
/// Get or set if transfer order records found
/// </summary>
/// <param name = "_recordsFound">Record found for the given critirea</param>
/// <returns>true or false</returns>
public boolean parmTransferOrderRecordsFound(boolean _recordsFound = recordsFound)
{
    recordsFound = _recordsFound;
    return recordsFound;
}
